// fixtures mirrors spec/ARC-v1-Wire-Fixtures.json (generated by
// spec/generate_arc_fixtures.py).
type fixtures struct {
	Packets struct {
		HandshakeInit struct {
			PacketHex string `json:"packet_hex"`
		} `json:"handshake_init"`
		HandshakeInitWithCookie struct {
			CookieHex string `json:"cookie_hex"`
			PacketHex string `json:"packet_hex"`
		} `json:"handshake_init_with_cookie"`
		HandshakeResp struct {
			PacketHex string `json:"packet_hex"`
		} `json:"handshake_resp"`
		CookieReply struct {
			PacketHex string `json:"packet_hex"`
		} `json:"cookie_reply"`
		StatelessReset struct {
			CIDHex        string `json:"cid_hex"`
			ResetTokenHex string `json:"reset_token_hex"`
			PacketHex     string `json:"packet_hex"`
		} `json:"stateless_reset"`
		NoisePrologueHex string `json:"noise_prologue_hex"`
	} `json:"packets"`
	Frames []struct {
		Name     string         `json:"name"`
		Type     int            `json:"type"`
		FrameHex string         `json:"frame_hex"`
		Fields   map[string]any `json:"fields"`
	} `json:"frames"`
	DataAEAD struct {
		DestCIDHex    string `json:"dest_cid_hex"`
		PacketNumber  uint64 `json:"packet_number"`
		EpochLow      uint8  `json:"epoch_low"`
		HeaderHex     string `json:"header_hex"`
		PlaintextHex  string `json:"plaintext_hex"`
		CiphertextHex string `json:"ciphertext_and_tag_hex"`
		PacketHex     string `json:"packet_hex"`
	} `json:"data_aead"`
	Cells struct {
		AssocIDHex   string   `json:"assoc_id_hex"`
		CellPacketID uint32   `json:"cell_packet_id"`
		PacketHex    string   `json:"packet_hex"`
		CellsHex     []string `json:"cells_hex"`
	} `json:"cells"`
	InvalidPackets []invalidCase `json:"invalid_packets"`
	InvalidCells   []invalidCase `json:"invalid_cells"`
	InvalidFrames  []invalidCase `json:"invalid_frames"`
}

type invalidCase struct {
	Name string `json:"name"`
	Hex  string `json:"hex"`
}

func loadFixtures(tb testing.TB) *fixtures {
	tb.Helper()
	data, err := os.ReadFile("../../spec/ARC-v1-Wire-Fixtures.json")
	if err != nil {
		tb.Fatal(err)
	}
	var f fixtures
	if err := json.Unmarshal(data, &f); err != nil {
		tb.Fatal(err)
	}
	return &f
}

func unhex(tb testing.TB, s string) []byte {
	tb.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		tb.Fatal(err)
	}
	return b
}

// parsePacket parses any packet type and re-encodes it.
func parsePacket(b []byte) ([]byte, error) {
	t, err := PeekType(b)
	if err != nil {
		return nil, err
	}
	switch t {
	case TypeHandshakeInit:
		p, err := ParseHandshakeInit(b)
		return p.Append(nil), err
	case TypeHandshakeResp:
		p, err := ParseHandshakeResp(b)
		return p.Append(nil), err
	case TypeCookieReply:
		p, err := ParseCookieReply(b)
		return p.Append(nil), err
	case TypeStatelessReset:
		p, err := ParseStatelessReset(b)
		return p.Append(nil), err
	case TypeData:
		h, _, ct, err := ParseData(b)
		return append(h.Append(nil), ct...), err
	case TypeCell:
		c, err := ParseCell(b)
		return c.Append(nil), err
	}
	panic("unreachable")
}

func TestFixturePacketsRoundTrip(t *testing.T) {
	f := loadFixtures(t)
	for name, h := range map[string]string{
		"handshake_init":             f.Packets.HandshakeInit.PacketHex,
		"handshake_init_with_cookie": f.Packets.HandshakeInitWithCookie.PacketHex,
		"handshake_resp":             f.Packets.HandshakeResp.PacketHex,
		"cookie_reply":               f.Packets.CookieReply.PacketHex,
		"stateless_reset":            f.Packets.StatelessReset.PacketHex,
		"data":                       f.DataAEAD.PacketHex,
	} {
		b := unhex(t, h)
		out, err := parsePacket(b)
		if err != nil {
			t.Errorf("%s: %v", name, err)
			continue
		}
		if !bytes.Equal(out, b) {
			t.Errorf("%s: re-encoded\n%x\nwant\n%x", name, out, b)
		}
	}
}

func TestFixtureHandshakeFields(t *testing.T) {
	f := loadFixtures(t)
	p, err := ParseHandshakeInit(unhex(t, f.Packets.HandshakeInitWithCookie.PacketHex))
	if err != nil {
		t.Fatal(err)
	}
	if got := hex.EncodeToString(p.Cookie[:]); got != f.Packets.HandshakeInitWithCookie.CookieHex {
		t.Errorf("cookie = %s", got)
	}
	if got := hex.EncodeToString(p.Prologue()); got != f.Packets.NoisePrologueHex {
		t.Errorf("prologue = %s, want %s", got, f.Packets.NoisePrologueHex)
	}

	r, err := ParseStatelessReset(unhex(t, f.Packets.StatelessReset.PacketHex))
	if err != nil {
		t.Fatal(err)
	}
	if hex.EncodeToString(r.CID[:]) != f.Packets.StatelessReset.CIDHex ||
		hex.EncodeToString(r.Token[:]) != f.Packets.StatelessReset.ResetTokenHex {
		t.Errorf("reset fields = %x %x", r.CID, r.Token)
	}
}

func TestFixtureData(t *testing.T) {
	f := loadFixtures(t)
	d := f.DataAEAD
	h, aad, ct, err := ParseData(unhex(t, d.PacketHex))
	if err != nil {
		t.Fatal(err)
	}
	if hex.EncodeToString(h.DestCID[:]) != d.DestCIDHex || h.PacketNumber != d.PacketNumber || h.EpochLow != d.EpochLow {
		t.Errorf("header = %+v", h)
	}
	if hex.EncodeToString(aad) != d.HeaderHex || hex.EncodeToString(ct) != d.CiphertextHex {
		t.Errorf("aad/ciphertext split wrong")
	}

	frames, err := ParseFrames(nil, unhex(t, d.PlaintextHex))
	if err != nil {
		t.Fatal(err)
	}
	var types []FrameType
	for _, fr := range frames {
		types = append(types, fr.Type())
	}
	if want := []FrameType{FrameAck, FramePing, FrameIPPacket}; !reflect.DeepEqual(types, want) {
		t.Errorf("frame types = %v, want %v", types, want)
	}
}

func TestFixtureFrames(t *testing.T) {
	f := loadFixtures(t)
	for _, fx := range f.Frames {
		t.Run(fx.Name, func(t *testing.T) {
			b := unhex(t, fx.FrameHex)
			fr, n, err := ParseFrame(b)
			if err != nil {
				t.Fatal(err)
			}
			if n != len(b) {
				t.Errorf("consumed %d of %d bytes", n, len(b))
			}
			if int(fr.Type()) != fx.Type {
				t.Errorf("type = %v, want %#x", fr.Type(), fx.Type)
			}
			if out := AppendFrame(nil, fr); !bytes.Equal(out, b) {
				t.Errorf("re-encoded %x, want %x", out, b)
			}
			checkFrameFields(t, fr, fx.Fields)
		})
	}
}

// checkFrameFields spot-checks decoded values against the generator's
// independent field listing.
func checkFrameFields(t *testing.T, fr Frame, fields map[string]any) {
	num := func(k string) uint64 { return uint64(fields[k].(float64)) }
	switch v := fr.(type) {
	case AuthResult:
		if v.TunMTU != uint16(num("tun_mtu")) || v.Prefix4 != uint8(num("prefix4")) ||
			v.KeepaliveMS != uint32(num("keepalive_ms")) || v.IdleMS != uint32(num("idle_ms")) ||
			v.IPv4 != [4]byte{10, 77, 0, 2} || v.DNSv4 != [4]byte{10, 77, 0, 1} {
			t.Errorf("AUTH_RESULT = %+v", v)
		}
	case IPFragment:
		if v.DatagramID != num("datagram_id") || v.TotalLen != uint16(num("total_len")) ||
			v.Offset != uint16(num("offset")) || hex.EncodeToString(v.Data) != fields["data_hex"] {
			t.Errorf("IP_FRAGMENT = %+v", v)
		}
	case IPDatagram:
		if v.DatagramID != num("datagram_id") || hex.EncodeToString(v.Packet) != fields["ip_packet_hex"] {
			t.Errorf("IP_DATAGRAM = %+v", v)
		}
	case FECRepair:
		if v.First32 != uint32(num("first32")) || v.Stride != uint8(num("stride")) || v.K != uint8(num("k")) ||
			v.M != uint8(num("m")) || v.Index != uint8(num("index")) || hex.EncodeToString(v.Data) != fields["data_hex"] {
			t.Errorf("FEC_REPAIR = %+v", v)
		}
	case FEC:
		if v.Seq != uint32(num("seq")) || v.Mode != FECMode(num("mode")) {
			t.Errorf("FEC = %+v", v)
		}
	case Redundancy:
		if v.Seq != uint32(num("seq")) || v.Mode != RedundancyMode(num("mode")) {
			t.Errorf("REDUNDANCY = %+v", v)
		}
	case StreamOpen:
		if v.ID != uint32(num("stream_id")) || v.Dst.String() != fields["dst"] {
			t.Errorf("STREAM_OPEN = %+v", v)
		}
	case Stream:
		if v.ID != uint32(num("stream_id")) || v.Offset != num("offset") || v.Fin != fields["fin"] ||
			hex.EncodeToString(v.Data) != fields["data_hex"] {
			t.Errorf("STREAM = %+v", v)
		}
	case MaxStreamData:
		if v.ID != uint32(num("stream_id")) || v.Max != num("max") {
			t.Errorf("MAX_STREAM_DATA = %+v", v)
		}
	case MaxData:
		if v.Max != num("max") {
			t.Errorf("MAX_DATA = %+v", v)
		}
	case StreamReset:
		if v.ID != uint32(num("stream_id")) || v.Code != ErrorCode(num("code")) || v.Final != num("final") {
			t.Errorf("STREAM_RESET = %+v", v)
		}
	case DiagOpen:
		if v.ID != uint32(num("stream_id")) {
			t.Errorf("DIAGNOSTICS_OPEN = %+v", v)
		}
	case InviteRequest:
		if hex.EncodeToString(v.RequestID[:]) != fields["request_id_hex"] {
			t.Errorf("INVITE_REQUEST = %+v", v)
		}
	case Invite:
		if hex.EncodeToString(v.RequestID[:]) != fields["request_id_hex"] || v.Status != ErrorCode(num("status")) ||
			hex.EncodeToString(v.ID[:]) != fields["invite_id_hex"] || hex.EncodeToString(v.Secret[:]) != fields["secret_hex"] ||
			v.Expires != uint32(num("expires")) {
			t.Errorf("INVITE = %+v", v)
		}
	case DevicesRequest:
		if hex.EncodeToString(v.RequestID[:]) != fields["request_id_hex"] {
			t.Errorf("DEVICES_REQUEST = %+v", v)
		}
	case Devices:
		list := fields["devices"].([]any)
		if hex.EncodeToString(v.RequestID[:]) != fields["request_id_hex"] || v.Status != ErrorCode(num("status")) || len(v.Devices) != len(list) {
			t.Errorf("DEVICES = %+v", v)
			break
		}
		for i, x := range v.Devices {
			want := list[i].(map[string]any)
			if hex.EncodeToString(x.ID[:]) != want["device_id_hex"] || hex.EncodeToString(x.Parent[:]) != want["parent_hex"] ||
				float64(x.Created) != want["created"] || float64(x.LastSeen) != want["last_seen"] ||
				hex.EncodeToString(x.Key[:]) != want["key_hex"] || x.Name != want["name"] {
				t.Errorf("DEVICES[%d] = %+v", i, x)
			}
		}
	case RevokeRequest:
		if hex.EncodeToString(v.RequestID[:]) != fields["request_id_hex"] || hex.EncodeToString(v.DeviceID[:]) != fields["device_id_hex"] ||
			v.Descendants != fields["descendants"] {
			t.Errorf("REVOKE_REQUEST = %+v", v)
		}
	case RevokeResult:
		if hex.EncodeToString(v.RequestID[:]) != fields["request_id_hex"] || v.Status != ErrorCode(num("status")) {
			t.Errorf("REVOKE_RESULT = %+v", v)
		}
	case Enrolled:
		if hex.EncodeToString(v.DeviceID[:]) != fields["device_id_hex"] || v.Name != fields["name"] {
			t.Errorf("ENROLLED = %+v", v)
		}
	case NewPath:
		if v.PathID != uint32(num("path_id")) || hex.EncodeToString(v.CID[:]) != fields["cid_hex"] ||
			hex.EncodeToString(v.ResetToken[:]) != fields["reset_token_hex"] {
			t.Errorf("NEW_PATH = %+v", v)
		}
	case Ack:
		if v.PathID != uint32(num("path_id")) || v.Largest != num("largest") ||
			v.AckDelayMicros != uint32(num("ack_delay_us")) || v.FirstRange != uint32(num("first_range")) {
			t.Errorf("ACK = %+v", v)
		}
		got, err := v.AppendIntervals(nil)
		if err != nil {
			t.Fatal(err)
		}
		var want []PacketRange
		for _, iv := range fields["intervals"].([]any) {
			p := iv.([]any)
			want = append(want, PacketRange{uint64(p[0].(float64)), uint64(p[1].(float64))})
		}
		if !reflect.DeepEqual(got, want) {
			t.Errorf("intervals = %v, want %v", got, want)
		}
	case Unknown:
		if fields["ignorable"] != true {
			t.Errorf("unexpected Unknown frame")
		}
	}
}

func TestFixtureCells(t *testing.T) {
	f := loadFixtures(t)
	want := unhex(t, f.Cells.PacketHex)
	got := make([]byte, len(want))
	filled := 0
	for _, h := range f.Cells.CellsHex {
		b := unhex(t, h)
		c, err := ParseCell(b)
		if err != nil {
			t.Fatal(err)
		}
		if hex.EncodeToString(c.AssocID[:]) != f.Cells.AssocIDHex || c.CellPacketID != f.Cells.CellPacketID ||
			int(c.TotalLen) != len(want) {
			t.Errorf("cell header = %+v", c)
		}
		filled += copy(got[c.Offset:], c.Chunk)
		if out := c.Append(nil); !bytes.Equal(out, b) {
			t.Errorf("re-encoded %x, want %x", out, b)
		}
	}
	if filled != len(want) || !bytes.Equal(got, want) {
		t.Errorf("reassembled %x, want %x", got, want)
	}
}

func TestFixtureInvalid(t *testing.T) {
	f := loadFixtures(t)
	check := func(kind string, cases []invalidCase, parse func([]byte) error) {
		for _, c := range cases {
			err := parse(unhex(t, c.Hex))
			if err == nil {
				t.Errorf("%s %q: accepted", kind, c.Name)
			} else if !errors.Is(err, ErrMalformed) && !errors.Is(err, ErrUnsupported) {
				t.Errorf("%s %q: error %v is neither malformed nor unsupported", kind, c.Name, err)
			}
		}
	}
	check("packet", f.InvalidPackets, func(b []byte) error { _, err := parsePacket(b); return err })
	check("cell", f.InvalidCells, func(b []byte) error { _, err := ParseCell(b); return err })
	check("frame", f.InvalidFrames, func(b []byte) error { _, err := ParseFrames(nil, b); return err })
}

func TestErrorClasses(t *testing.T) {
	if _, err := ParseFrames(nil, []byte{0x7f, 0, 0}); !errors.Is(err, ErrUnsupported) || errors.Is(err, ErrMalformed) {
		t.Errorf("unknown required frame: %v", err)
	}
	if _, err := ParseFrames(nil, []byte{0x0a, 0}); !errors.Is(err, ErrMalformed) || errors.Is(err, ErrUnsupported) {
		t.Errorf("truncated frame: %v", err)
	}
	if _, err := PeekType([]byte{0x09}); !errors.Is(err, ErrUnsupported) {
		t.Errorf("unknown packet type: %v", err)
	}
}

func TestParseFramesRejectsWholePayload(t *testing.T) {
	p := AppendFrame(nil, Ping{})
	p = append(p, 0x7f, 0, 0) // unknown required frame after a valid one
	dst := []Frame{Padding{}}
	out, err := ParseFrames(dst, p)
	if err == nil || len(out) != 1 {
		t.Fatalf("got %d frames, err %v; want the original dst and an error", len(out), err)
	}
}

func TestAppendFramePanicsOnOversizedValue(t *testing.T) {
	defer func() {
		if recover() == nil {
			t.Error("no panic")
		}
	}()
	AppendFrame(nil, Unknown{FrameType: 0x80, Value: make([]byte, 0x10000)})
}

func TestAppendIPPacketMatchesAppendFrame(t *testing.T) {
	pkt := make([]byte, 300)
	pkt[0] = 0x45
	pkt[2], pkt[3] = 0x01, 0x2c
	want := AppendFrame(nil, IPPacket{Packet: pkt})
	if got := AppendIPPacket(nil, pkt); !bytes.Equal(got, want) {
		t.Fatalf("AppendIPPacket = %x\nwant %x", got[:8], want[:8])
	}
	want = AppendFrame(nil, IPDatagram{DatagramID: 0x0102030405060708, Packet: pkt})
	if got := AppendIPDatagram(nil, 0x0102030405060708, pkt); !bytes.Equal(got, want) {
		t.Fatalf("AppendIPDatagram = %x\nwant %x", got[:16], want[:16])
	}
	buf := make([]byte, 0, 512)
	if allocs := testing.AllocsPerRun(100, func() { AppendIPPacket(buf, pkt); AppendIPDatagram(buf, 1, pkt) }); allocs != 0 {
		t.Errorf("AppendIPPacket/AppendIPDatagram allocate %v times", allocs)
	}
}
